CREATE DATABASE IF NOT EXISTS shopsphere_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE shopsphere_db;
CREATE TABLE IF NOT EXISTS users(uid INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(30),address TEXT,role ENUM('customer','admin') DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(category_id INT AUTO_INCREMENT PRIMARY KEY,category_name VARCHAR(100) UNIQUE NOT NULL,description VARCHAR(255));
CREATE TABLE IF NOT EXISTS products(product_id INT AUTO_INCREMENT PRIMARY KEY,product_name VARCHAR(180) NOT NULL,category_id INT NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,discount DECIMAL(5,2) DEFAULT 0,stock_quantity INT DEFAULT 0,image_url TEXT,featured TINYINT DEFAULT 0,active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(category_id),CHECK(price>=0),CHECK(discount BETWEEN 0 AND 90),CHECK(stock_quantity>=0));
CREATE TABLE IF NOT EXISTS orders(order_id INT AUTO_INCREMENT PRIMARY KEY,order_code VARCHAR(30) UNIQUE NOT NULL,user_id INT NOT NULL,order_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,total_amount DECIMAL(12,2) NOT NULL,order_status ENUM('Placed','Processing','Shipped','Delivered','Cancelled') DEFAULT 'Placed',shipping_address TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(uid));
CREATE TABLE IF NOT EXISTS order_items(item_id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,subtotal DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(order_id),FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE IF NOT EXISTS payments(payment_id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,payment_method VARCHAR(60),payment_status VARCHAR(40),FOREIGN KEY(order_id) REFERENCES orders(order_id));
